cases.bad:
highlightedRef.current?.scrollIntoView({
  behavior: 'smooth', // animate scroll từ 0 → middle → long animation → disorienting
  block: 'center',
});
// panel open hoặc seek far: list ở top, highlighted cue ở middle
// smooth animate qua toàn bộ list → motion sickness

cases.good:
highlightedRef.current?.scrollIntoView({
  behavior: 'auto', // instant scroll, no animation — jump thẳng đến highlighted cue
  block: 'center',
});
// user không bị disorient, có thể scroll manual nếu muốn xem context
